import { useEffect } from 'react'

import { Box } from '@mui/material'

import TextEditor, { type TextEditorHandle } from 'src/components/TextEditor'

const ClubIntroduction: React.FC<{ content: string; editorRef: React.RefObject<TextEditorHandle> }> = ({
  content,
  editorRef
}) => {
  useEffect(() => {
    editorRef.current?.setHTML(content || '')
  }, [content])
  return (
    <Box mt={4}>
      <TextEditor
        initialValue={content}
        ref={editorRef}
        toolbarItems={[
          ['heading', 'bold', 'italic', 'strike'],
          ['hr', 'quote'],
          ['ul', 'ol', 'task'],
          ['image', 'link'],
          ['code', 'codeblock']
        ]}
      />
    </Box>
  )
}

export default ClubIntroduction
